starterCode.pennylane:
import pennylane as qml
dev = qml.device("default.qubit", wires=2)
@qml.qnode(dev)
def circuit():
    qml.Hadamard(0)
    qml.Hadamard(1)
    qml.CZ(wires=[0, 1])
    return qml.state()

